using System;
using System.Collections.Generic;
using Framework.Grid;
using UnityEngine;

namespace Framework.Pathfinding
{
    /// <summary>
    /// グリッド上の指定された起点から、
    /// 到達可能な各セルへの最短移動距離を管理する。
    /// </summary>
    /// <typeparam name="T">グリッドのセルデータ型</typeparam>
    /// <remarks>
    /// 幅優先探索を使用して距離を一括計算する。
    /// 上下左右の4方向移動に対応し、
    /// すべての移動コストを1として扱う。
    /// グリッド変更時の再計算は呼び出し側が担当する。
    /// </remarks>
    public sealed class GridDistanceMap<T>
    {
        /// <summary>
        /// 到達不可能なセルを表す距離。
        /// </summary>
        public const int UnreachableDistance = -1;

        /// <summary>
        /// 探索に使用する上下左右の移動方向。
        /// </summary>
        private static readonly Vector2Int[] Directions =
        {
            Vector2Int.up,
            Vector2Int.down,
            Vector2Int.left,
            Vector2Int.right
        };

        /// <summary>
        /// 距離計算の対象となるグリッド。
        /// </summary>
        private readonly GridMap<T> map;

        /// <summary>
        /// セルへの進入可否を判定する処理。
        /// </summary>
        private readonly Func<Vector2Int, bool> canEnterCell;

        /// <summary>
        /// 各セルへの最短移動距離。
        /// </summary>
        private readonly int[,] distances;

        /// <summary>
        /// 幅優先探索に使用するキュー。
        /// </summary>
        private readonly Queue<Vector2Int> searchQueue;

        /// <summary>
        /// 最後に計算した距離マップの起点。
        /// </summary>
        private Vector2Int origin;

        /// <summary>
        /// 有効な距離マップが計算されているか。
        /// </summary>
        private bool isCalculated;

        /// <summary>
        /// 距離計算の実行中であるか。
        /// </summary>
        private bool isCalculating;

        /// <summary>
        /// 起点から到達可能なセルの総数。
        /// </summary>
        private int reachableCount;

        /// <summary>
        /// 起点から到達可能な最大距離。
        /// </summary>
        private int maxDistance = UnreachableDistance;

        /// <summary>
        /// 起点から最も遠いセルの座標。
        /// </summary>
        private Vector2Int farthestPosition;

        /// <summary>
        /// 計算結果の変更を識別するためのバージョン。
        /// </summary>
        private int resultVersion;

        /// <summary>
        /// 距離計算の対象となるグリッド。
        /// </summary>
        public GridMap<T> Map => map;

        /// <summary>
        /// 距離計算の起点。
        /// 未計算の場合は既定値を返す。
        /// </summary>
        public Vector2Int Origin => origin;

        /// <summary>
        /// 有効な距離マップが計算されているか。
        /// </summary>
        public bool IsCalculated => isCalculated;

        /// <summary>
        /// 起点を含む到達可能セルの総数。
        /// </summary>
        public int ReachableCount => reachableCount;

        /// <summary>
        /// 起点から到達可能な最大距離。
        /// 未計算の場合は-1を返す。
        /// </summary>
        public int MaxDistance => maxDistance;

        /// <summary>
        /// 距離マップを生成する。
        /// </summary>
        /// <param name="map">計算対象のグリッド</param>
        /// <param name="canEnterCell">
        /// セルへの進入可否を判定する処理
        /// </param>
        /// <exception cref="ArgumentNullException">
        /// 必須の引数が指定されていない場合。
        /// </exception>
        public GridDistanceMap(
            GridMap<T> map,
            Func<Vector2Int, bool> canEnterCell)
        {
            if (map == null)
            {
                throw new ArgumentNullException(nameof(map));
            }

            if (canEnterCell == null)
            {
                throw new ArgumentNullException(
                    nameof(canEnterCell));
            }

            this.map = map;
            this.canEnterCell = canEnterCell;

            // グリッドと同じ大きさの距離配列を確保する。
            distances = new int[map.Width, map.Height];

            // 探索用キューを生成し、再計算時にも使用する。
            searchQueue = new Queue<Vector2Int>();

            ClearInternal();
        }

        /// <summary>
        /// 指定された起点から距離マップを計算する。
        /// </summary>
        /// <param name="newOrigin">距離計算の起点</param>
        /// <returns>
        /// 有効な距離マップを計算できた場合はtrue
        /// </returns>
        /// <remarks>
        /// 起点が無効な場合は既存の計算結果を破棄する。
        /// 計算中にグリッドや通行条件を変更してはならない。
        /// </remarks>
        public bool Calculate(Vector2Int newOrigin)
        {
            EnsureNotCalculating();

            ClearInternal();

            isCalculating = true;

            try
            {
                // グリッド外や通行不可能な起点を拒否する。
                if (!map.IsInside(newOrigin) ||
                    !canEnterCell(newOrigin))
                {
                    return false;
                }

                origin = newOrigin;

                distances[origin.x, origin.y] = 0;

                reachableCount = 1;
                maxDistance = 0;

                farthestPosition = origin;

                searchQueue.Enqueue(origin);

                // 幅優先探索によって最短距離を計算する。
                while (searchQueue.Count > 0)
                {
                    Vector2Int current =
                        searchQueue.Dequeue();

                    int nextDistance =
                        distances[current.x, current.y] + 1;

                    for (int i = 0; i < Directions.Length; i++)
                    {
                        Vector2Int next =
                            current + Directions[i];

                        // グリッド外のセルは探索しない。
                        if (!map.IsInside(next))
                        {
                            continue;
                        }

                        // 計算済みのセルは再探索しない。
                        if (distances[next.x, next.y] !=
                            UnreachableDistance)
                        {
                            continue;
                        }

                        // 通行不可能なセルは探索しない。
                        if (!canEnterCell(next))
                        {
                            continue;
                        }

                        // キューへの追加時点で距離を確定する。
                        distances[next.x, next.y] =
                            nextDistance;

                        reachableCount++;

                        // 最も遠いセルの情報を更新する。
                        if (nextDistance > maxDistance)
                        {
                            maxDistance = nextDistance;
                            farthestPosition = next;
                        }

                        searchQueue.Enqueue(next);
                    }
                }

                isCalculated = true;

                return true;
            }
            catch
            {
                // 計算途中の不完全な結果を残さない。
                ClearInternal();

                throw;
            }
            finally
            {
                searchQueue.Clear();

                isCalculating = false;
            }
        }

        /// <summary>
        /// 指定されたセルへの最短移動距離を取得する。
        /// </summary>
        /// <param name="position">取得対象のセル座標</param>
        /// <returns>
        /// 最短移動距離。
        /// 未計算、範囲外、到達不可能の場合は-1
        /// </returns>
        public int GetDistance(Vector2Int position)
        {
            if (!isCalculated || !map.IsInside(position))
            {
                return UnreachableDistance;
            }

            return distances[position.x, position.y];
        }

        /// <summary>
        /// 指定されたセルへの最短移動距離を取得する。
        /// </summary>
        /// <param name="position">取得対象のセル座標</param>
        /// <param name="distance">取得した最短移動距離</param>
        /// <returns>
        /// 到達可能な距離を取得できた場合はtrue
        /// </returns>
        public bool TryGetDistance(
            Vector2Int position,
            out int distance)
        {
            distance = GetDistance(position);

            return distance != UnreachableDistance;
        }

        /// <summary>
        /// 指定されたセルが起点から到達可能か確認する。
        /// </summary>
        /// <param name="position">判定対象のセル座標</param>
        /// <returns>到達可能な場合はtrue</returns>
        public bool IsReachable(Vector2Int position)
        {
            return GetDistance(position) !=
                UnreachableDistance;
        }

        /// <summary>
        /// 指定されたセルが起点から指定距離以内にあるか確認する。
        /// </summary>
        /// <param name="position">判定対象のセル座標</param>
        /// <param name="distanceLimit">許容する最大距離</param>
        /// <returns>指定距離以内の場合はtrue</returns>
        public bool IsWithinDistance(
            Vector2Int position,
            int distanceLimit)
        {
            if (distanceLimit < 0)
            {
                return false;
            }

            int distance = GetDistance(position);

            return distance != UnreachableDistance &&
                distance <= distanceLimit;
        }

        /// <summary>
        /// 到達可能なすべてのセルを列挙する。
        /// </summary>
        /// <returns>到達可能なセル座標の列挙</returns>
        /// <remarks>
        /// Y座標、X座標の順に列挙する。
        /// 距離順には並べ替えない。
        /// 列挙中に距離マップを変更してはならない。
        /// </remarks>
        public IEnumerable<Vector2Int>
            GetReachablePositions()
        {
            return GetPositionsWithinDistance(int.MaxValue);
        }

        /// <summary>
        /// 起点から指定距離以内のセルを列挙する。
        /// </summary>
        /// <param name="distanceLimit">許容する最大距離</param>
        /// <returns>指定距離以内のセル座標の列挙</returns>
        /// <remarks>
        /// 列挙中に計算結果が変更された場合は例外を発生させる。
        /// 未計算または負の距離が指定された場合は空の列挙を返す。
        /// </remarks>
        public IEnumerable<Vector2Int>
            GetPositionsWithinDistance(int distanceLimit)
        {
            if (!isCalculated || distanceLimit < 0)
            {
                yield break;
            }

            int version = resultVersion;

            for (int y = 0; y < map.Height; y++)
            {
                for (int x = 0; x < map.Width; x++)
                {
                    EnsureResultVersion(version);

                    int distance = distances[x, y];

                    if (distance != UnreachableDistance &&
                        distance <= distanceLimit)
                    {
                        yield return new Vector2Int(x, y);
                    }
                }
            }

            EnsureResultVersion(version);
        }

        /// <summary>
        /// 起点から最も遠い到達可能セルを取得する。
        /// </summary>
        /// <param name="position">最も遠いセルの座標</param>
        /// <param name="distance">起点からの最短移動距離</param>
        /// <returns>セルを取得できた場合はtrue</returns>
        /// <remarks>
        /// 同じ最大距離のセルが複数存在する場合は、
        /// 幅優先探索で最初に発見したセルを返す。
        /// </remarks>
        public bool TryGetFarthestPosition(
            out Vector2Int position,
            out int distance)
        {
            position = default;
            distance = UnreachableDistance;

            if (!isCalculated)
            {
                return false;
            }

            position = farthestPosition;
            distance = maxDistance;

            return true;
        }

        /// <summary>
        /// 計算結果を初期化する。
        /// </summary>
        /// <remarks>
        /// 距離配列と探索用キューは破棄せず再利用する。
        /// </remarks>
        public void Clear()
        {
            EnsureNotCalculating();

            ClearInternal();
        }

        /// <summary>
        /// 内部の計算結果を初期化する。
        /// </summary>
        private void ClearInternal()
        {
            isCalculated = false;

            origin = default;
            farthestPosition = default;

            reachableCount = 0;
            maxDistance = UnreachableDistance;

            searchQueue.Clear();

            // すべてのセルを未到達状態に戻す。
            for (int y = 0; y < map.Height; y++)
            {
                for (int x = 0; x < map.Width; x++)
                {
                    distances[x, y] = UnreachableDistance;
                }
            }

            // 既存の列挙処理を無効化する。
            unchecked
            {
                resultVersion++;
            }
        }

        /// <summary>
        /// 距離計算中ではないことを確認する。
        /// </summary>
        /// <exception cref="InvalidOperationException">
        /// 距離計算中に状態変更が要求された場合。
        /// </exception>
        private void EnsureNotCalculating()
        {
            if (isCalculating)
            {
                throw new InvalidOperationException(
                    "距離計算中は計算結果を変更できません。");
            }
        }

        /// <summary>
        /// 計算結果のバージョンが一致することを確認する。
        /// </summary>
        /// <param name="version">列挙開始時のバージョン</param>
        /// <exception cref="InvalidOperationException">
        /// 列挙中に計算結果が変更された場合。
        /// </exception>
        private void EnsureResultVersion(int version)
        {
            if (version != resultVersion)
            {
                throw new InvalidOperationException(
                    "セルの列挙中に距離マップが変更されました。");
            }
        }
    }
}
